import {initializeApp} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-app.js';
import {getAuth,onAuthStateChanged,signInWithEmailAndPassword,signOut,sendPasswordResetEmail,createUserWithEmailAndPassword,initializeAuth,inMemoryPersistence,deleteUser} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js';
import {getFirestore,doc,collection,onSnapshot,runTransaction,serverTimestamp,setDoc,updateDoc} from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js';
import {firebaseConfig} from './firebase-config.js';
const auth=getAuth(initializeApp(firebaseConfig)),db=getFirestore();
let stopProfile=()=>{},stopEvents=()=>{},stopMembers=()=>{},generation=0,eventGeneration=0,profile=null;
const cloud=window.CommissionCloud={user:null,profile:null,ready:false,revision:0,onData:null,members:[],membersError:"",onMembers:null};
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function errorText(e){if(e.code==='permission-denied')return 'Access denied. Ask Governance to check your user profile and Firestore rules.';if(e.code==='auth/operation-not-allowed')return 'Enable Email/Password in Firebase Authentication first.';if(e.code==='auth/invalid-credential')return 'Email or password is incorrect.';return e.message||'Unable to connect. Please retry.';}
function gate(message='Sign in to view shared commission rates.'){cloud.ready=false;$('modal').close();$('app').innerHTML=`<section class="login-card"><div class="eyebrow">GOVERNANCE / MARKETPLACE OPERATIONS</div><h1>Commission Tracker</h1><p>${escape(message)}</p>${auth.currentUser?`<p>Your user ID: <code>${escape(auth.currentUser.uid)}</code></p><button id="logout">Sign out</button>`:`<form id="login"><label>Email<input id="email" type="email" autocomplete="username" required></label><label>Password<input id="password" type="password" autocomplete="current-password" required minlength="6"></label><div class="actions field"><button class="primary" id="signin">Sign in</button><button type="button" id="reset">Reset password</button></div></form>`}<p id="authmessage" role="status"></p></section>`;if($('logout'))$('logout').onclick=()=>signOut(auth);if($('login')){$('login').onsubmit=async e=>{e.preventDefault();$('signin').disabled=true;try{await signInWithEmailAndPassword(auth,$('email').value.trim(),$('password').value);}catch(err){$('authmessage').textContent=errorText(err);$('signin').disabled=false;}};$('reset').onclick=async()=>{const email=$('email').value.trim();if(!email){$('authmessage').textContent='Enter your email first.';return;}try{await sendPasswordResetEmail(auth,email);$('authmessage').textContent='If the account exists, a reset email will be sent.';}catch(err){$('authmessage').textContent=errorText(err);}};}}
cloud.canEdit=region=>cloud.ready&&profile?.active===true&&(profile.role==='admin'||(profile.role==='pic'&&profile.regions?.includes(region)));
cloud.signOut=()=>signOut(auth);
cloud.save=async(batch,expectedRevision)=>{
 if(!cloud.ready||!auth.currentUser)throw Error('Shared data is not connected. Reconnect before saving.');
 if(!navigator.onLine)throw Error('You are offline. Reconnect before saving.');
 const user=auth.currentUser,regions=[...new Set(batch.patches.map(p=>p.region))];if(regions.some(r=>!cloud.canEdit(r)))throw Error('You can only update your assigned regions.');
 if(batch.patches.length>400)throw Error('Upload at most 400 changed categories at a time.');
 const entries=batch.patches.map((patch,i)=>{const changes=batch.changes.filter(c=>c.region===patch.region&&c.channel===patch.channel&&JSON.stringify(c.cats)===JSON.stringify(patch.cats));const event={region:patch.region,patch,changes,batchId:batch.id,id:batch.id,seq:0,inputAt:batch.inputAt,inputDate:batch.inputDate,effectiveDate:batch.effectiveDate,by:profile.name||user.email,uid:user.uid,reference:batch.reference,reason:batch.reason,mode:batch.mode,source:batch.source,uploadScope:batch.uploadScope||'scoped',missing:i===0?batch.missing:[],createdAt:serverTimestamp()};if(new TextEncoder().encode(JSON.stringify(event)).length>800000)throw Error('A category update is too large. Split the upload.');return {ref:doc(collection(db,'commissionEvents')),event};});
 const counter=doc(db,'commissionMeta','revision');
 await runTransaction(db,async tx=>{const snap=await tx.get(counter),revision=snap.exists()?snap.data().value:0;if(revision!==expectedRevision)throw Error('Another PIC saved an update while you were reviewing. Close this preview and preview your changes again.');const next=revision+1;entries.forEach(({ref,event})=>tx.set(ref,{...event,seq:next}));tx.set(counter,{value:next,updatedAt:serverTimestamp(),batchId:batch.id,eventId:entries[0].ref.id});});
};
let appLoadPromise=null,delivery=0;
async function receive(snapshot,gen,eventGen){if(gen!==generation||eventGen!==eventGeneration)return;const received=++delivery;const groups=new Map();for(const item of snapshot.docs){const e=item.data(),patch={...e.patch,region:e.region};let b=groups.get(e.batchId);if(!b){b={id:e.batchId,seq:e.seq,inputAt:e.inputAt,inputDate:e.inputDate,effectiveDate:e.effectiveDate,by:e.by,uid:e.uid,reference:e.reference||'',reason:e.reason,mode:e.mode,source:e.source,uploadScope:e.uploadScope,patches:[],changes:[],missing:[]};groups.set(e.batchId,b);}b.patches.push(patch);b.changes.push(...e.changes.map(c=>({...c,region:e.region,channel:patch.channel,cats:patch.cats})));b.missing.push(...(e.missing||[]));}const batches=[...groups.values()].sort((a,b)=>a.seq-b.seq);if(!appLoadPromise){appLoadPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='app.js';script.onload=resolve;script.onerror=reject;document.body.append(script);});}await appLoadPromise;if(gen===generation&&eventGen===eventGeneration&&received===delivery){cloud.revision=Math.max(0,...batches.map(b=>b.seq));cloud.ready=!snapshot.metadata.fromCache;cloud.onData?.({version:1,batches});}}
cloud.showGate=gate;
onAuthStateChanged(auth,user=>{const gen=++generation;stopProfile();stopEvents();stopMembers();cloud.members=[];cloud.user=user;cloud.profile=null;profile=null;gate(user?'Checking your access…':undefined);if(!user)return;stopProfile=onSnapshot(doc(db,'commissionUsers',user.uid),snapshot=>{stopEvents();stopMembers();cloud.members=[];const eventGen=++eventGeneration;profile=snapshot.exists()?snapshot.data():null;cloud.profile=profile;if(profile?.active!==true||!['admin','pic','viewer'].includes(profile.role)){gate('Your account is not assigned yet. Ask Governance to activate your access.');return;}if(profile.role==='admin'){stopMembers=onSnapshot(collection(db,'commissionUsers'),snap=>{cloud.members=snap.docs.map(d=>({uid:d.id,...d.data()}));cloud.membersError='';cloud.onMembers?.();},e=>{cloud.membersError=errorText(e);cloud.onMembers?.();});}gate('Loading shared records…');stopEvents=onSnapshot(collection(db,'commissionEvents'),{includeMetadataChanges:true},s=>receive(s,gen,eventGen).catch(e=>gate(errorText(e))),e=>gate(errorText(e)));},e=>gate(errorText(e)));});
window.addEventListener('offline',()=>{cloud.ready=false;cloud.onData?.(null);});

let provisioningAuth=null,provisioningBusy=false;
function requireAdmin(){if(!cloud.ready||profile?.active!==true||profile.role!=='admin'||!auth.currentUser)throw Error('Only an active administrator can manage members.');if(!navigator.onLine)throw Error('Reconnect before managing members.');}
function memberFields(input){const name=String(input.name||'').trim(),role=input.role,regions=[...new Set(input.regions||[])];if(!name||name.length>100||!['admin','pic','viewer'].includes(role)||regions.some(r=>!['SG','MY','PH','TH','VN','ID'].includes(r)))throw Error('Enter a name, valid role and assigned regions.');if(role==='pic'&&!regions.length)throw Error('Assign at least one region to a Regional PIC.');return {name,role,regions:role==='admin'?['SG','MY','PH','TH','VN','ID']:role==='viewer'?[]:regions,active:input.active===true};}
cloud.addMember=async input=>{requireAdmin();if(provisioningBusy)throw Error('Member creation is already in progress.');const fields=memberFields(input),email=String(input.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter a valid email.');let password=String(input.password||'');if(!password){const bytes=new Uint8Array(24);crypto.getRandomValues(bytes);password='Aa1!'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}if(password.length<8)throw Error('Use at least 8 characters for the initial password.');provisioningBusy=true;let user=null;try{if(!provisioningAuth)provisioningAuth=initializeAuth(initializeApp(firebaseConfig,'member-provisioning'),{persistence:inMemoryPersistence});user=(await createUserWithEmailAndPassword(provisioningAuth,email,password)).user;requireAdmin();await setDoc(doc(db,'commissionUsers',user.uid),{...fields,email,createdAt:serverTimestamp(),updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});return {uid:user.uid,email};}catch(e){if(user){try{await deleteUser(user);}catch{throw Error('Login was created but access setup failed. Recover user '+user.uid+' in Firebase Console before retrying.');}}if(e.code==='auth/email-already-in-use')throw Error('This email already has a login. Use Add existing login with its Firebase UID.');throw e;}finally{password='';if(provisioningAuth)await signOut(provisioningAuth).catch(()=>{});provisioningBusy=false;}};
cloud.updateMember=async(uid,input)=>{requireAdmin();const fields=memberFields(input);if(uid===auth.currentUser.uid&&(!fields.active||fields.role!=='admin'))throw Error('You cannot disable or remove your own admin access.');await updateDoc(doc(db,'commissionUsers',uid),{...fields,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});};
cloud.linkMember=async(uid,input)=>{requireAdmin();if(!/^[A-Za-z0-9_-]{1,128}$/.test(uid))throw Error('Enter the existing Authentication user UID.');const fields=memberFields(input),email=String(input.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Enter the existing login email.');await runTransaction(db,async tx=>{const ref=doc(db,'commissionUsers',uid);if((await tx.get(ref)).exists())throw Error('Member already exists. Use Edit access.');tx.set(ref,{...fields,email,createdAt:serverTimestamp(),updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});});};
cloud.resetMember=async member=>{requireAdmin();if(!member.email)throw Error('Add the member email first.');await sendPasswordResetEmail(auth,member.email);};
